INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Beginnt eine Klasse-A-Adresse immer mit 0?', 2, '[{"text": "Ja", "correct": true, "because": "Erstes Bit ist 0"}, {"text": "Nein", "correct": false, "because": "Klassenregel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Klasse nutze ich für ein großes Unternehmensnetzwerk?', 3, '[{"text": "Klasse A", "correct": true, "because": "Viele Hosts möglich"}, {"text": "Klasse C", "correct": false, "because": "Wenige Hosts"}, {"text": "Klasse D", "correct": false, "because": "Multicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Klasse B hat 16 Netzwerkbits. b) Klasse E ist für normale Netze.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Klasse E ist experimentell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Klassendefinition?', 4, '[{"text": "Erstes Bit", "correct": false, "because": "Definiert die Klasse"}, {"text": "Netzwerkbits", "correct": false, "because": "Bestimmen Bereich"}, {"text": "Farbcodierung", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 224.0.0.0 zu Klasse D gehört?', 2, '[{"text": "Ja", "correct": true, "because": "Multicast-Bereich"}, {"text": "Nein", "correct": false, "because": "Passt zur Definition"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse gehört zu Klasse C?', 3, '[{"text": "192.168.1.0", "correct": true, "because": "Erste Bits 110"}, {"text": "10.0.0.0", "correct": false, "because": "Klasse A"}, {"text": "172.16.0.0", "correct": false, "because": "Klasse B"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Klassen sind für Unicast gedacht?', 5, '[{"text": "A", "correct": true, "because": "Normale Netze"}, {"text": "B", "correct": true, "because": "Mittlere Netze"}, {"text": "D", "correct": false, "because": "Multicast"}, {"text": "E", "correct": false, "because": "Experimentell"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Klasse C hat 24 Netzwerkbits. b) Klasse A ist für kleine Netze. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Klasse A für große Netze"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Klasseneinteilung?', 4, '[{"text": "Erste Bits", "correct": false, "because": "Bestimmen die Klasse"}, {"text": "Netzwerkgröße", "correct": false, "because": "Impliziert durch Klasse"}, {"text": "Betriebssystem", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat Klasse B 16 Hostbits?', 2, '[{"text": "Ja", "correct": true, "because": "32 - 16 Netzwerkbits"}, {"text": "Nein", "correct": false, "because": "Korrekte Aufteilung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Bereich gehört zu Klasse E?', 4, '[{"text": "240.0.0.0 - 255.255.255.255", "correct": true, "because": "Erste Bits 1111"}, {"text": "192.0.0.0 - 223.255.255.255", "correct": false, "because": "Klasse C"}, {"text": "128.0.0.0 - 191.255.255.255", "correct": false, "because": "Klasse B"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Klasse D für normale Geräte ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Multicast"}, {"text": "Ja", "correct": false, "because": "Falsche Zuordnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Klassenauswahl?', 3, '[{"text": "Netzwerkgröße", "correct": true, "because": "Bestimmt Klasse"}, {"text": "Schnelligkeit", "correct": false, "because": "Nicht relevant"}, {"text": "Design", "correct": false, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Klasse A hat 8 Netzwerkbits. b) Klasse C ist für Multicast.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Klasse C ist Unicast"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat Klasse B?', 5, '[{"text": "16 Netzwerkbits", "correct": true, "because": "Feste Definition"}, {"text": "16 Hostbits", "correct": true, "because": "Rest der 32 Bits"}, {"text": "Multicast", "correct": false, "because": "Klasse D"}, {"text": "8 Hostbits", "correct": false, "because": "Klasse C"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Klassendefinition unwichtig?', 3, '[{"text": "Bitmuster", "correct": false, "because": "Definiert Klasse"}, {"text": "Adressbereich", "correct": false, "because": "Bestimmt Einsatz"}, {"text": "Schriftart", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist 127.0.0.1 Klasse A?', 3, '[{"text": "Ja", "correct": true, "because": "Bereich 0-127"}, {"text": "Nein", "correct": false, "because": "Passt zur Definition"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Klasse E öffentlich genutzt wird?', 2, '[{"text": "Nein", "correct": true, "because": "Experimentell reserviert"}, {"text": "Ja", "correct": false, "because": "Nicht für Normalnutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Klasse hat die Adresse 239.1.2.3?', 4, '[{"text": "Klasse D", "correct": true, "because": "Multicast, 224-239"}, {"text": "Klasse C", "correct": false, "because": "192-223"}, {"text": "Klasse E", "correct": false, "because": "240-255"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Klasse wähle ich für ein kleines LAN?', 3, '[{"text": "Klasse C", "correct": true, "because": "Wenige Hosts, 24 Bits"}, {"text": "Klasse A", "correct": false, "because": "Zu groß"}, {"text": "Klasse D", "correct": false, "because": "Multicast"}]');
